// GroupByParam groups by the given page parameter key's value and with the given order.
// Valid values for order is asc, desc, rev and reverse.
func (p Pages) GroupByParam(key string, order ...string) (PagesGroup, error) {
	if len(p) < 1 {
		return nil, nil
	}

	direction := "asc"
	if len(order) > 0 {
		switch strings.ToLower(order[0]) {
		case "desc", "rev", "reverse":
			direction = "desc"
		}
	}

	paramKey := strings.ToLower(key)
	var tmp reflect.Value
	var keyt reflect.Type
	for _, e := range p {
		rawParam := e.Params()[paramKey]
		if rawParam == nil {
			continue
		}
		param := resource.GetParamToLower(e, key)
		if param != nil {
			if _, ok := param.([]string); !ok {
				keyt = reflect.TypeOf(param)
				tmp = reflect.MakeMap(reflect.MapOf(keyt, pagesType))
				break
			}
		}
	}
	if !tmp.IsValid() {
		return nil, errors.New("there is no such param")
	}

	for _, e := range p {
		param := resource.GetParam(e, key)
		if reflect.TypeOf(param) != keyt {
			continue
		}
		pageValue := reflect.ValueOf(e)
		paramValue := reflect.ValueOf(param)
		groupedPages := tmp.MapIndex(paramValue)
		if !groupedPages.IsValid() {
			emptyGroup := reflect.MakeSlice(pagesType, 0, 0)
			tmp.SetMapIndex(paramValue, emptyGroup)
			groupedPages = tmp.MapIndex(paramValue)
		}
		updatedGroup := reflect.Append(groupedPages, pageValue)
		tmp.SetMapIndex(paramValue, updatedGroup)
	}

	groupedKeys := tmp.MapKeys()
	if len(groupedKeys) > 1 {
		switch groupedKeys[0].Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			intKeys := mapKeyByInt{groupedKeys}
			if direction == "desc" {
				sort.Sort(sort.Reverse(intKeys))
			} else {
				sort.Sort(intKeys)
			}
		case reflect.String:
			examplePage := p[0]
			stringLess, closeCollator := collatorStringLess(examplePage)
			defer closeCollator()
			stringKeys := mapKeyByStr{
				less:         stringLess,
				mapKeyValues: groupedKeys,
			}
			if direction == "desc" {
				sort.Sort(sort.Reverse(stringKeys))
			} else {
				sort.Sort(stringKeys)
			}
		}
	}

	var grouped PagesGroup
	for _, groupedKey := range groupedKeys {
		groupPages := tmp.MapIndex(groupedKey).Interface().(Pages)
		grouped = append(grouped, PageGroup{
			Key:   groupedKey.Interface(),
			Pages: groupPages,
		})
	}

	return grouped, nil
}

func (p Pages) groupByDateField(format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	if len(p) < 1 {
		return nil, nil
	}

	sp := sorter(p)

	if !(len(order) > 0 && (strings.ToLower(order[0]) == "asc" || strings.ToLower(order[0]) == "rev" || strings.ToLower(order[0]) == "reverse")) {
		sp = sp.Reverse()
	}

	if sp == nil {
		return nil, nil
	}

	firstPage := sp[0]
	date := getDate(firstPage)

	// Pages may be a mix of multiple languages, so we need to use the language
	// for the currently rendered Site.
	currentSite := firstPage.Site().Current()
	formatter := langs.GetTimeFormatter(currentSite.Language())
	formatted := formatter.Format(date, format)
	var r []PageGroup
	r = append(r, PageGroup{Key: formatted, Pages: make(Pages, 0)})
	r[0].Pages = append(r[0].Pages, sp[0])

	i := 0
	for _, e := range sp[1:] {
		date = getDate(e)
		formatted := formatter.Format(date, format)
		if r[i].Key.(string) != formatted {
			r = append(r, PageGroup{Key: formatted})
			i++
		}
		r[i].Pages = append(r[i].Pages, e)
	}
	return r, nil
}

